const raw = $input.first().json;
const body = raw.body ?? raw;
const perfil = body.perfil && typeof body.perfil === 'object' ? body.perfil : {};

const pick = (key) => {
  if (body[key] !== undefined && body[key] !== null && body[key] !== '') return body[key];
  if (perfil[key] !== undefined && perfil[key] !== null && perfil[key] !== '') return perfil[key];
  return undefined;
};

const conexaoId = body.conexaoId || body.conexao_id;
const acao = String(body.acao || body.action || 'consultar').toLowerCase();

if (!conexaoId) throw new Error('Campo conexaoId obrigatorio.');
if (!['consultar', 'sincronizar', 'atualizar'].includes(acao)) {
  throw new Error('acao deve ser consultar, sincronizar ou atualizar.');
}

const verticals = ["OTHER", "AUTO", "BEAUTY", "APPAREL", "EDU", "ENTERTAIN", "EVENT_PLAN", "FINANCE", "GROCERY", "GOVT", "HOTEL", "HEALTH", "NONPROFIT", "PROF_SERVICES", "RETAIL", "TRAVEL", "RESTAURANT", "ALCOHOL", "ONLINE_GAMBLING", "PHYSICAL_GAMBLING", "OTC_DRUGS", "MATRIMONY_SERVICE"];

const payload = {
  conexaoId,
  acao,
  about: pick('about'),
  description: pick('description'),
  address: pick('address'),
  email: pick('email'),
  vertical: pick('vertical'),
  websites: body.websites ?? perfil.websites,
  foto_base64: body.foto_base64 || body.fotoBase64 || null,
  foto_mime: body.foto_mime || body.fotoMime || null
};

if (acao === 'atualizar') {
  const hasField = (key) => {
    const value = payload[key];
    if (key === 'websites') return Array.isArray(value) && value.length > 0;
    if (key === 'foto_base64') return typeof value === 'string' && value.length > 0;
    return value !== undefined && value !== null && value !== '';
  };

  if (!['about', 'description', 'address', 'email', 'vertical', 'websites', 'foto_base64'].some(hasField)) {
    throw new Error('Informe ao menos um campo para atualizar.');
  }

  if (hasField('about')) {
    const about = String(payload.about).trim();
    if (about.length < 1 || about.length > 139) {
      throw new Error('about deve ter entre 1 e 139 caracteres.');
    }
    payload.about = about;
  }

  if (hasField('description')) {
    const description = String(payload.description).trim();
    if (description.length < 1 || description.length > 512) {
      throw new Error('description deve ter entre 1 e 512 caracteres.');
    }
    payload.description = description;
  }

  if (hasField('address')) {
    const address = String(payload.address).trim();
    if (address.length < 1 || address.length > 256) {
      throw new Error('address deve ter entre 1 e 256 caracteres.');
    }
    payload.address = address;
  }

  if (hasField('email')) {
    const email = String(payload.email).trim();
    if (email.length > 128 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      throw new Error('email invalido (max 128 caracteres, formato valido).');
    }
    payload.email = email;
  }

  if (hasField('vertical')) {
    const vertical = String(payload.vertical).trim().toUpperCase();
    if (!verticals.includes(vertical)) {
      throw new Error(`vertical invalido. Use um valor da enum Meta, ex: OTHER, RETAIL, RESTAURANT.`);
    }
    payload.vertical = vertical;
  }

  if (payload.websites !== undefined && payload.websites !== null) {
    if (!Array.isArray(payload.websites)) throw new Error('websites deve ser array.');
    if (payload.websites.length > 2) throw new Error('websites max 2 URLs.');
    payload.websites = payload.websites
      .map((url) => String(url).trim())
      .filter(Boolean);
    if (!payload.websites.length) delete payload.websites;
    for (const url of payload.websites || []) {
      if (url.length > 256) throw new Error('cada URL max 256 caracteres.');
      if (!/^https?:\/\//i.test(url)) throw new Error('URLs devem comecar com http:// ou https://');
    }
  }

  if (hasField('foto_base64')) {
    let b64 = String(payload.foto_base64).trim();
    const dataUrlMatch = b64.match(/^data:image\/\w+;base64,(.+)$/i);
    if (dataUrlMatch) b64 = dataUrlMatch[1];
    b64 = b64.replace(/\s/g, '').replace(/-/g, '+').replace(/_/g, '/');
    payload.foto_base64 = b64;

    const buffer = Buffer.from(b64, 'base64');
    if (!buffer.length) throw new Error('foto_base64 invalida.');
    if (buffer.length > 5 * 1024 * 1024) throw new Error('Foto max 5MB.');

    const isJpeg = buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
    const isPng = buffer.length >= 8 && buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47;
    const isWebp = buffer.length >= 12 && buffer.toString('ascii', 0, 4) === 'RIFF' && buffer.toString('ascii', 8, 12) === 'WEBP';

    if (!isJpeg) {
      if (isPng) throw new Error('Meta exige JPG. Converta PNG para JPEG no front (canvas.toBlob image/jpeg).');
      if (isWebp) throw new Error('Meta exige JPG. Converta WebP para JPEG no front.');
      throw new Error('Foto de perfil deve ser JPG (image/jpeg).');
    }

    payload.foto_mime = 'image/jpeg';
  }
}

return [{ json: payload }];

const entrada = $('VALIDAR ENTRADA').first().json;
const conexao = $('DADOS CONEXAO').first().json;
const config = $('CONFIG API OFICIAL').first().json;

if (!config?.app_id) {
  throw new Error('Config API Oficial incompleta em SAAS_Config_ApiOficial.');
}
if (!conexao?.access_token || !conexao?.phone_number_id) {
  throw new Error('Conexao nao encontrada ou sem phone_number_id.');
}
if (!conexao.waba_id) {
  throw new Error('Conexao sem waba_id.');
}
if (!conexao.apiOficial) {
  throw new Error('Conexao nao e API Oficial.');
}

return [
  {
    json: {
      ...entrada,
      access_token: conexao.access_token,
      phone_number_id: conexao.phone_number_id,
      waba_id: conexao.waba_id,
      business_id: conexao.business_id,
      app_id: config.app_id,
      conexaoRow: conexao
    }
  }
];

const entrada = $('VALIDAR CONEXAO').first().json;
const row = entrada.conexaoRow;

const TIER_LABELS = {
  TIER_50: '50 conversas / 24h',
  TIER_250: '250 conversas / 24h',
  TIER_2K: '2.000 conversas / 24h',
  TIER_10K: '10.000 conversas / 24h',
  TIER_100K: '100.000 conversas / 24h',
  TIER_UNLIMITED: 'Ilimitado',
  UNTIERED: 'Sem limite definido'
};

const PHONE_STATUS_LABELS = {
  CONNECTED: 'Conectado',
  DISCONNECTED: 'Desconectado',
  PENDING: 'Pendente',
  DELETED: 'Excluido',
  MIGRATED: 'Migrado',
  BANNED: 'Banido',
  RESTRICTED: 'Restrito',
  RATE_LIMITED: 'Limitado',
  UNVERIFIED: 'Nao verificado'
};

const BIZ_VERIFICATION_LABELS = {
  verified: 'Verificado',
  not_verified: 'Nao verificado',
  pending: 'Pendente',
  failed: 'Falhou',
  rejected: 'Rejeitado'
};

const ACCOUNT_REVIEW_LABELS = {
  APPROVED: 'Aprovado',
  PENDING: 'Pendente',
  REJECTED: 'Rejeitado'
};

const NAME_STATUS_LABELS = {
  APPROVED: 'Aprovado',
  AVAILABLE_WITHOUT_REVIEW: 'Disponivel sem revisao',
  DECLINED: 'Recusado',
  EXPIRED: 'Expirado',
  PENDING_REVIEW: 'Em revisao',
  NONE: 'Sem certificado'
};

const parseMetaPagamento = (value) => {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return [value];
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
};

const formatPhone = (telefone) => {
  if (!telefone) return null;
  const d = String(telefone).replace(/\D/g, '');
  if (d.length >= 12 && d.startsWith('55')) {
    return `+${d.slice(0, 2)} ${d.slice(2, 4)} ${d.slice(4)}`;
  }
  return `+${d}`;
};

const getLinhaCredito = (metaPagamento, primaryFundingId, wabaStatus) => {
  const wabaSt = String(wabaStatus || '').toUpperCase();
  if (wabaSt === 'PENDING_VALID_PAYMENT_METHOD') {
    return { status: 'pending_valid_payment_method', label: 'Forma de pagamento pendente' };
  }
  if (primaryFundingId) {
    return { status: 'active', label: 'Configurada' };
  }
  const arr = Array.isArray(metaPagamento) ? metaPagamento : [];
  const billing = arr.find((c) => c?.configuration_name === 'billing_meta_api');
  if (billing?.pending_valid_payment_method) {
    return { status: 'pending_valid_payment_method', label: 'Forma de pagamento pendente' };
  }
  if (billing?.has_payment_method || billing?.primary_funding_id) {
    return { status: 'active', label: 'Configurada' };
  }
  for (let i = arr.length - 1; i >= 0; i--) {
    const cfg = arr[i];
    if (!cfg || cfg.configuration_name === 'billing_meta_api') continue;
    const st = String(cfg?.status || cfg?.credit_line_status || '').toLowerCase();
    if (st && !st.includes('need') && !st.includes('pending') && !st.includes('update')) {
      return { status: st, label: 'Configurada' };
    }
  }
  return { status: 'needs_update', label: 'Atualizacao necessaria' };
};

const limite = row.metaMessagingLimit || row.metaPhoneQualityLimit || null;
const metaPagamento = parseMetaPagamento(row.metaPagamento);
const billing = metaPagamento.find((c) => c?.configuration_name === 'billing_meta_api') || null;
const linhaCredito = getLinhaCredito(metaPagamento, row.metaPrimaryFundingId || null, row.metaWabaStatus || billing?.waba_status || null);
const perfil = row.metaPerfil || {};

return [
  {
    json: {
      ok: true,
      acao: 'consultar',
      conexaoId: entrada.conexaoId,
      cache: true,
      dados: {
        nomeExibir: row.metaVerifiedName || row.NomeConexao || null,
        nomeStatus: row.metaNameStatus || null,
        nomeStatusLabel: NAME_STATUS_LABELS[row.metaNameStatus] || row.metaNameStatus || 'Sem informacao',
        novoNomeExibir: row.metaNewDisplayName || null,
        novoNomeStatus: row.metaNewNameStatus || null,
        novoNomeStatusLabel: NAME_STATUS_LABELS[row.metaNewNameStatus] || row.metaNewNameStatus || null,
        telefone: row.Telefone || null,
        telefoneFormatado: formatPhone(row.Telefone),
        fotoPerfil: row.FotoPerfil || perfil.profile_picture_url || null,
        wabaId: row.waba_id || null,
        phoneNumberId: row.phone_number_id || null,
        businessId: row.business_id || null,
        limiteMensagens: limite,
        limiteMensagensLabel: TIER_LABELS[limite] || limite || 'Sem informacao',
        statusNumero: row.metaPhoneStatus || null,
        statusNumeroLabel: PHONE_STATUS_LABELS[row.metaPhoneStatus] || row.metaPhoneStatus || 'Sem informacao',
        qualidade: row.metaQualityRating || null,
        verificacaoEmpresarial: row.metaBusinessVerificationStatus || null,
        verificacaoEmpresarialLabel: BIZ_VERIFICATION_LABELS[row.metaBusinessVerificationStatus] || row.metaBusinessVerificationStatus || 'Sem informacao',
        statusConta: row.metaAccountReviewStatus || null,
        statusContaLabel: ACCOUNT_REVIEW_LABELS[row.metaAccountReviewStatus] || row.metaAccountReviewStatus || 'Sem informacao',
        linhaCredito: linhaCredito.status,
        linhaCreditoLabel: linhaCredito.label,
        statusWaba: row.metaWabaStatus || billing?.waba_status || null,
