        fusoHorarioId: row.metaWabaTimezoneId || billing?.timezone_id || null,
        formaPagamentoPendente: (row.metaWabaStatus || billing?.waba_status) === 'PENDING_VALID_PAYMENT_METHOD'
          || billing?.pending_valid_payment_method === true,
        numerosWaba: billing?.phone_numbers || [],
        metaPagamento,
        metaPagamentoUpdatedAt: row.metaPagamentoUpdatedAt || null,
        metaPrimaryFundingId: row.metaPrimaryFundingId || null,
        atualizadoEm: row.metaDadosUpdatedAt || row.metaPerfilUpdatedAt || null
      },
      perfil
    }
  }
];

const prev = $('VALIDAR CONEXAO').first().json;
const token = prev.access_token;
const headers = { Authorization: `Bearer ${token}` };

const metaErrorMessage = (err) => {
  const apiErr = err?.response?.body?.error || err?.response?.data?.error || err?.error;
  return apiErr?.error_user_msg || apiErr?.message || err?.message || String(err);
};

const req = async (url, qs = {}, optional = false) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      qs,
      headers,
      json: true
    });
    if (res?.error) {
      if (optional) return { error: res.error };
      throw new Error(res.error.error_user_msg || res.error.message || 'Falha na Meta API.');
    }
    return res;
  } catch (err) {
    if (optional) return { error: { message: metaErrorMessage(err) } };
    throw new Error(metaErrorMessage(err));
  }
};

const [wabaRes, phoneNumbersRes, perfilRes] = await Promise.all([
  req(`https://graph.facebook.com/v25.0/${prev.waba_id}`, {
    fields: 'id,name,message_template_namespace,account_review_status,business_verification_status,whatsapp_business_manager_messaging_limit'
  }),
  req(`https://graph.facebook.com/v25.0/${prev.waba_id}/phone_numbers`, {
    fields: 'id,display_phone_number,verified_name,code_verification_status,quality_rating,status'
  }),
  req(`https://graph.facebook.com/v25.0/${prev.phone_number_id}/whatsapp_business_profile`, {
    fields: 'about,address,description,email,profile_picture_url,websites,vertical,messaging_product'
  })
]);

let phoneDetailRes = await req(
  `https://graph.facebook.com/v25.0/${prev.phone_number_id}`,
  {
    fields: 'status,verified_name,display_phone_number,quality_rating,code_verification_status,name_status,new_display_name,new_name_status'
  },
  true
);
if (phoneDetailRes?.error) {
  phoneDetailRes = await req(
    `https://graph.facebook.com/v25.0/${prev.phone_number_id}`,
    {
      fields: 'status,verified_name,display_phone_number,quality_rating,code_verification_status'
    },
    true
  );
}

const phoneNumbers = Array.isArray(phoneNumbersRes?.data) ? phoneNumbersRes.data : [];
const phoneFromList = phoneNumbers.find((p) => String(p.id) === String(prev.phone_number_id)) || phoneNumbers[0] || {};
const phoneRes = phoneDetailRes?.error ? phoneFromList : { ...phoneFromList, ...phoneDetailRes };

const perfil = Array.isArray(perfilRes.data) && perfilRes.data.length ? perfilRes.data[0] : {};
const telefone = phoneRes.display_phone_number
  ? String(phoneRes.display_phone_number).replace(/\D/g, '')
  : prev.conexaoRow?.Telefone || null;

const limite = wabaRes.whatsapp_business_manager_messaging_limit
  || prev.conexaoRow?.metaMessagingLimit
  || prev.conexaoRow?.metaPhoneQualityLimit
  || null;

const now = new Date().toISOString();

return [
  {
    json: {
      ...prev,
      syncPayload: {
        Telefone: telefone,
        FotoPerfil: perfil.profile_picture_url || prev.conexaoRow?.FotoPerfil || null,
        metaVerifiedName: phoneRes.verified_name || null,
        metaNameStatus: phoneRes.name_status || null,
        metaNewDisplayName: phoneRes.new_display_name || null,
        metaNewNameStatus: phoneRes.new_name_status || null,
        metaPhoneStatus: phoneRes.status || null,
        metaQualityRating: phoneRes.quality_rating || null,
        metaBusinessVerificationStatus: wabaRes.business_verification_status || null,
        metaAccountReviewStatus: wabaRes.account_review_status || null,
        metaMessagingLimit: limite,
        metaWabaName: wabaRes.name || null,
        metaPerfil: perfil,
        metaPerfilUpdatedAt: now,
        metaDadosUpdatedAt: now
      }
    }
  }
];

