const prev = $('VALIDAR CONEXAO').first().json;
const webhook = $('WEBHOOK PERFIL').first().json;
const body = webhook.body ?? webhook;
const perfilReq = body.perfil && typeof body.perfil === 'object' ? body.perfil : {};

const wasInBody = (key) =>
  Object.prototype.hasOwnProperty.call(body, key) ||
  Object.prototype.hasOwnProperty.call(perfilReq, key);

const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const wasEdited = (key) => {
  if (!wasInBody(key)) return false;
  const rawVal = body[key] !== undefined ? body[key] : perfilReq[key];
  if (key === 'websites') {
    return Array.isArray(rawVal) && rawVal.some((u) => str(u) !== '');
  }
  return rawVal !== undefined && rawVal !== null && str(rawVal) !== '';
};

const getJpegDimensions = (buffer) => {
  let i = 2;
  while (i < buffer.length - 8) {
    if (buffer[i] !== 0xff) { i++; continue; }
    const marker = buffer[i + 1];
    if (marker === 0xd9) break;
    const len = buffer.readUInt16BE(i + 2);
    if (len < 2 || i + 2 + len > buffer.length) break;
    if ([0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].includes(marker)) {
      return { height: buffer.readUInt16BE(i + 5), width: buffer.readUInt16BE(i + 7) };
    }
    i += 2 + len;
  }
  return null;
};

const valueOf = (key) => {
  const rawVal = body[key] !== undefined ? body[key] : perfilReq[key];
  if (key === 'websites') {
    if (!Array.isArray(rawVal)) return [];
    return rawVal.map((u) => str(u)).filter(Boolean);
  }
  if (key === 'vertical') return str(rawVal).toUpperCase();
  return str(rawVal);
};

const temFoto = !!(prev.foto_base64);
const hasTextFieldsEdited = ['about', 'description', 'address', 'email', 'vertical', 'websites'].some(wasEdited);

if (!hasTextFieldsEdited && !temFoto) {
  throw new Error('Nenhum campo para atualizar.');
}

const textBody = { messaging_product: 'whatsapp' };

if (wasEdited('about')) {
  const about = valueOf('about');
  if (!about || about.length > 139) throw new Error('about deve ter entre 1 e 139 caracteres.');
  textBody.about = about;
}

if (wasEdited('description')) {
  const description = valueOf('description');
  if (!description || description.length > 512) throw new Error('description deve ter entre 1 e 512 caracteres.');
  textBody.description = description;
}

if (wasEdited('address')) {
  const address = valueOf('address');
  if (!address || address.length > 256) throw new Error('address deve ter entre 1 e 256 caracteres.');
  textBody.address = address;
}

if (wasEdited('email')) {
  const email = valueOf('email');
  if (!email || email.length > 128 || !emailRe.test(email)) {
    throw new Error('email invalido (formato e max 128 caracteres).');
  }
  textBody.email = email;
}

if (wasEdited('vertical')) {
  const vertical = valueOf('vertical');
  const allowed = ['OTHER','AUTO','BEAUTY','APPAREL','EDU','ENTERTAIN','EVENT_PLAN','FINANCE','GROCERY','GOVT','HOTEL','HEALTH','NONPROFIT','PROF_SERVICES','RETAIL','TRAVEL','RESTAURANT','ALCOHOL','ONLINE_GAMBLING','PHYSICAL_GAMBLING','OTC_DRUGS','MATRIMONY_SERVICE'];
  if (!vertical || !allowed.includes(vertical)) {
    throw new Error('vertical invalido. Ex: RETAIL, RESTAURANT, HEALTH, OTHER.');
  }
  textBody.vertical = vertical;
}

if (wasEdited('websites')) {
  const websites = valueOf('websites');
  if (!websites.length) throw new Error('websites deve ter ao menos 1 URL valida.');
  if (websites.length > 2) throw new Error('websites max 2 URLs.');
  for (const url of websites) {
    if (url.length > 256) throw new Error('cada URL max 256 caracteres.');
    if (!/^https?:\/\//i.test(url)) throw new Error('URLs devem comecar com http:// ou https://');
  }
  textBody.websites = websites;
}

const hasTextPayload = Object.keys(textBody).length > 1;
let foto_length = 0;

if (temFoto) {
  const buffer = Buffer.from(prev.foto_base64, 'base64');
  foto_length = buffer.length;
  if (!foto_length) throw new Error('foto_base64 invalida.');
  if (foto_length > 5 * 1024 * 1024) throw new Error('Foto max 5MB.');
  const isJpeg = buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
  if (!isJpeg) throw new Error('Meta exige JPG na foto de perfil. Envie image/jpeg.');
  const dims = getJpegDimensions(buffer);
  if (!dims || dims.width < 192 || dims.height < 192) {
    throw new Error('Foto de perfil deve ser JPG com no minimo 192x192 pixels.');
  }
}

if (hasTextFieldsEdited && !hasTextPayload) {
  throw new Error('Nenhum campo de texto valido para enviar a Meta.');
}

return [{
