    access_token: prev.access_token,
    phone_number_id: prev.phone_number_id,
    app_id: prev.app_id,
    textBody,
    hasText: hasTextPayload,
    hasPhoto: temFoto,
    temFoto,
    foto_length
  },
  ...(temFoto ? {
    binary: {
      foto: {
        data: prev.foto_base64,
        mimeType: 'image/jpeg',
        fileName: 'profile.jpg'
      }
